/**
 * Bundles the public popup, tabs, menu, float and widget scripts into strings the HTML/CSS export writes
 * next to exported pages (W-963). The package ships TypeScript source, so the bundles are
 * generated here and committed; `export-runtimes.test.ts` fails when they are out of date.
 *
 *   bun scripts/build-export-runtimes.ts          # rewrite the generated file
 */
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
const ASTRO = join(ROOT, "packages/emvb/src/astro");
export const GENERATED = join(ROOT, "packages/emvb/src/core/export/runtimes.generated.ts");

const RUNTIMES = {
  popups: ["popups/runtime.ts", "initPopups"],
  tabs: ["tabs/runtime.ts", "initTabs"],
  menu: ["menu/runtime.ts", "initMenus"],
  floats: ["floats/runtime.ts", "initFloats"],
  alerts: ["widgets/alerts.ts", "initAlerts"],
  lightbox: ["widgets/lightbox.ts", "initLightbox"],
  carousel: ["widgets/carousel.ts", "initCarousels"],
} as const;

async function bundle(file: string, init: string): Promise<string> {
  const entry = join(ASTRO, `.export-entry-${init}.ts`);
  await Bun.write(entry, `import { ${init} } from "./${file}";\n${init}();\n`);
  try {
    const result = await Bun.build({
      entrypoints: [entry],
      format: "iife",
      minify: true,
      target: "browser",
    });
    if (!result.success) throw new Error(result.logs.map(String).join("\n"));
    const output = result.outputs[0];
    if (!output) throw new Error(`No output for ${file}`);
    return (await output.text()).trim();
  } finally {
    await Bun.file(entry).delete();
  }
}

/** The generated module's source. */
export async function generatedSource(): Promise<string> {
  const lines = [
    "// Generated by scripts/build-export-runtimes.ts (W-963). Do not edit; run the script.",
    "",
    "/** The public runtime scripts, bundled, for pages in an HTML/CSS export. */",
    "export const EXPORT_RUNTIMES = {",
  ];
  for (const [name, [file, init]] of Object.entries(RUNTIMES)) {
    // oxlint-disable-next-line no-await-in-loop -- one temporary entry file at a time
    lines.push(`  ${name}: ${JSON.stringify(await bundle(file, init))},`);
  }
  lines.push("} as const;", "");
  return lines.join("\n");
}

if (import.meta.main) {
  await Bun.write(GENERATED, await generatedSource());
  // oxlint-disable-next-line no-console -- a CLI script reports what it wrote
  console.log(`Wrote ${GENERATED}`);
}
